from pathlib import Path
import json, re

p = Path('kak-obyasnit-neponyatnoe-pismo-s-pomoshchyu-ii/index.html')
s = p.read_text(encoding='utf-8-sig')

repls = {
'<title>Как понять документ с помощью нейросети: письмо, срок и действия</title>': '<title>Как объяснить непонятное письмо с помощью ИИ — банк, налоговая, Госуслуги</title>',
'<meta name="description" content="Как понять документ с помощью нейросети: выяснить, что от вас хотят, какой срок указан, что будет без ответа и где это написано."/>': '<meta name="description" content="Как объяснить текст непонятного письма из банка, налоговой или Госуслуг с помощью ИИ: понять смысл, сроки, требования и что делать дальше."/>',
'<meta property="og:title" content="Как объяснить непонятное письмо с помощью ИИ"/>': '<meta property="og:title" content="Как объяснить непонятное письмо с помощью ИИ — банк, налоговая, Госуслуги"/>',
'<meta property="og:description" content="Разбираем документ по пяти вопросам: что от вас хотят, какой срок, что будет без ответа, где это написано и что перепроверить."/>': '<meta property="og:description" content="Как понять смысл письма из банка, налоговой или Госуслуг: требования, сроки, последствия и готовые промпты для разбора."/>',
'<meta name="twitter:description" content="Как понять документ и проверить требования, сроки и последствия по исходному тексту."/>': '<meta name="twitter:description" content="Разбираем непонятное письмо простыми словами: смысл, требования, сроки и что делать дальше."/>',
'<meta property="article:modified_time" content="2026-08-12T00:00:00+03:00"/>': '<meta property="article:modified_time" content="2026-08-15T00:00:00+03:00"/>',
'<p class="seo-lead">Приходит письмо из налоговой, банка или другой организации. Нейросеть поможет понять документ: что от вас хотят, какой срок указан, что будет без ответа и где именно это написано. Важные детали после разбора нужно сверить с оригиналом.</p>': '<p class="seo-lead">Если пришло непонятное письмо из банка, налоговой, Госуслуг или другой организации и вы не поняли его смысл, нейросеть поможет объяснить текст простыми словами: что от вас хотят, какой срок указан, что будет без ответа и что делать дальше. Важные даты, суммы и требования после разбора нужно сверить с оригиналом.</p>',
'<small>Обновлено: 12 августа 2026</small>': '<small>Обновлено: 15 августа 2026</small>'
}
for old, new in repls.items():
    if old not in s:
        raise SystemExit(f'Missing expected fragment: {old[:80]}')
    s = s.replace(old, new, 1)

m = re.search(r'<script type="application/ld\+json">(\{"@context":"https://schema.org","@type":"Article".*?\})</script>', s)
if not m:
    raise SystemExit('Article JSON-LD not found')
article = json.loads(m.group(1))
article['description'] = 'Как объяснить текст непонятного письма из банка, налоговой или Госуслуг с помощью ИИ: понять смысл, сроки, требования и что делать дальше.'
article['dateModified'] = '2026-08-15'
article_json = json.dumps(article, ensure_ascii=False, separators=(',', ':'))
s = s[:m.start(1)] + article_json + s[m.end(1):]

m = re.search(r'<script type="application/ld\+json">(\{"@context":"https://schema.org","@type":"FAQPage".*?\})</script>', s)
if not m:
    raise SystemExit('FAQ JSON-LD not found')
faq = json.loads(m.group(1))
extra = [
    ('Что делать, если не понял смысл письма?', 'Скопируйте текст письма или загрузите чёткое фото и попросите ИИ отдельно назвать: кто пишет, что от вас хотят, срок, последствия бездействия и фрагмент письма, на котором основан каждый вывод.'),
    ('Как объяснить письмо из банка простыми словами?', 'Попросите нейросеть сначала определить, что это: реклама, уведомление об изменении условий или требование. Затем отдельно выпишите суммы, даты, комиссии, сроки и действия, которые от вас ожидают.'),
    ('Как понять письмо из налоговой или с Госуслуг?', 'Попросите ИИ назвать ведомство, основание обращения, требуемое действие, срок и последствия. После этого обязательно сверяйте даты, суммы, реквизиты и ссылки на нормы с самим документом и официальным источником.')
]
existing = {q.get('name') for q in faq['mainEntity']}
for name, text in extra:
    if name not in existing:
        faq['mainEntity'].append({'@type':'Question','name':name,'acceptedAnswer':{'@type':'Answer','text':text}})
faq_json = json.dumps(faq, ensure_ascii=False, separators=(',', ':'))
s = s[:m.start(1)] + faq_json + s[m.end(1):]

visible = '''<section class="template-section" id="faq-search"><h2>Если письмо непонятно: три частых вопроса</h2><h3>Что делать, если не понял смысл письма?</h3><p>Передайте нейросети текст целиком и попросите не пересказывать его вообще, а ответить по пунктам: кто пишет, что от вас хотят, какой срок, что будет без ответа и где именно это написано.</p><h3>Как объяснить письмо из банка простыми словами?</h3><p>Сначала определите тип письма: реклама, уведомление об изменении условий или требование. Затем отдельно проверьте суммы, даты, комиссии и действия, которые банк ожидает от вас.</p><h3>Как понять письмо из налоговой или с Госуслуг?</h3><p>Попросите назвать ведомство, основание обращения, требуемое действие, срок и последствия. Даты, суммы, реквизиты и ссылки на нормы после ответа ИИ сверяйте с оригиналом и официальным источником.</p><p>Если ответ нейросети вызывает сомнения, используйте отдельный гайд «<a href="/kak-proverit-ne-sovrala-li-neyroset/">Как проверить, не соврала ли нейросеть</a>».</p></section>'''
if 'id="faq-search"' not in s:
    marker = '</div></article>'
    if marker not in s:
        raise SystemExit('Article closing marker not found')
    s = s.replace(marker, visible + marker, 1)

assert 'Как объяснить непонятное письмо с помощью ИИ — банк, налоговая, Госуслуги' in s
assert 'id="faq-search"' in s
assert s.count('Что делать, если не понял смысл письма?') >= 2
assert '2026-08-15' in s
assert '111385663' in s, 'Metrika counter must be preserved'

p.write_text('\ufeff' + s, encoding='utf-8')
